(()=>{'use strict';const d=window.CASE1_REPORT,E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),N=n=>String(Number(Number(n).toFixed(4)));
const q=d.qwen,fmt=b=>b?b[0]===b[1]?N(b[0]):N(b[0])+'–'+N(b[1]):'待评';document.querySelector('#qwen-score').textContent=q? q.score!=null?N(q.score):fmt(q.score_bounds_conditional_on_frozen_inventory):'评审中';
document.querySelector('#qwen-status').textContent=q?(q.score!=null?'复核完成':'条件分数区间 · 正式复核总分待核验'):'实际声画证据逐项评审中';
const names={detection:'检出与误报控制',factual_correction:'事实纠正',audio_localization:'音频区间定位',timing_precision:'时间精度',video_evidence:'视频证据',score_reconstruction:'累计比分',delivery:'交付'};const max={detection:30,factual_correction:35,audio_localization:5,timing_precision:10,video_evidence:10,score_reconstruction:5,delivery:5};
document.querySelector('#breakdown').innerHTML=Object.keys(names).map(k=>`<tr><td>${names[k]}</td><td>${max[k]}</td><td>${N(d.original.breakdown[k])}</td><td>${fmt(q?.breakdown_bounds[k])}</td></tr>`).join('');
document.querySelector('#policy-note').textContent='检出分类、音频IoU、数值时间测量、交付检查沿用冻结规则；事实纠正、证据相关性和比分由Qwen复核。若源参考或额外问题存在争议，区间仅在原22项清单成立的条件下有效。';
document.querySelector('#reference-pending').textContent=q?JSON.stringify(q.pending):'评审进行中';
document.querySelector('#flags').innerHTML=d.flags.map(f=>`<details><summary>${E(f.id)} · ${E(f.issue_type)} · ${E(f.quote)}</summary><p><button data-time="${f.audio_span[0]}">播放 ${f.audio_span[0]}s</button></p><p>${E(f.reason)}</p><p><b>模型建议：</b>${E(f.correction)}</p><pre>${E(JSON.stringify(f.corrected_facts,null,2))}</pre><div class="links">${f.evidence.map(e=>`<a href="submission/${E(e.path)}" target="_blank">${e.time}s原帧</a>`).join('')}</div></details>`).join('');
document.querySelector('#flags').addEventListener('click',e=>{const b=e.target.closest('[data-time]');if(b){const v=document.querySelector('#source');v.currentTime=Number(b.dataset.time);v.scrollIntoView({block:'center',behavior:'smooth'});}});
function render(){const f=document.querySelector('#filter').value;document.querySelector('#judge').innerHTML=q?q.items.filter(x=>f==='all'||Object.values(x.answers).some(a=>a.value===f)).map(x=>`<details><summary>${E(x.id)} · ${x.vote_count}轮 · ${Object.values(x.answers).filter(a=>a.value==='pending').length}待核验</summary>${Object.entries(x.answers).map(([k,a])=>`<div><h4>${E(k)}：${E(a.value)} <small>票 ${E(a.votes.join(' / '))}</small></h4>${a.reasons.map((r,i)=>`<p>${i+1}. ${E(r)} <small>源时间 ${E(a.source_times[i].join(', '))}</small></p>`).join('')}</div>`).join('')}</details>`).join(''):'Qwen评审进行中';}
document.querySelector('#filter').addEventListener('change',render);render();})();